import { app, BrowserWindow, ipcMain } from 'electron';
import path from 'path';
import axios from 'axios';
import * as cheerio from 'cheerio';
import puppeteer, { executablePath } from 'puppeteer-core';


interface ParseConfig {
  type: string;
  data: string;
}

function createWindow() {
  const mainWindow = new BrowserWindow({
    width: 1200,
    height: 800,
    webPreferences: {
      // Правильный путь к прелоад-скрипту
      preload: path.join(__dirname, '../../preload/preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true
    }
  });

  if (process.env.NODE_ENV === 'development') {
    mainWindow.loadURL('http://localhost:39143');
    mainWindow.webContents.openDevTools();
  } else {
    mainWindow.loadFile(path.join(__dirname, '../renderer/index.html'));
  }
}

app.whenReady().then(() => {
  createWindow();
  
  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});

// Реализация функций парсинга
async function parseHtmlContent(url: string, selector: string): Promise<string[]> {
  try {
    const response = await axios.get(url);
    const $ = cheerio.load(response.data);
    const results: string[] = [];
    
    $(selector).each((_: any, element: any) => {
      results.push($(element).text().trim());
    });
    
    return results;
  } catch (error) {
    throw new Error(`HTML parsing failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

async function parseDynamicContent(url: string, selector: string): Promise<string[]> {
  let browser;
  try {
    browser = await puppeteer.launch({
      executablePath: executablePath(),
      headless: true,
      args: ['--no-sandbox', '--disable-setuid-sandbox']
    });
    
    const page = await browser.newPage();
    await page.goto(url, { waitUntil: 'networkidle2' });
    
    return await page.$$eval(selector, elements => 
      elements.map(el => el.textContent?.trim() || '')
    );
  } catch (error) {
    throw new Error(`Dynamic content parsing failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
  } finally {
    if (browser) await browser.close();
  }
}

// Обработчики IPC
ipcMain.on('parse:html', async (event, url: string, selector: string) => {
  try {
    const data = await parseHtmlContent(url, selector);
    event.sender.send('parse:html:response', { 
      success: true, 
      data 
    });
  } catch (error) {
    event.sender.send('parse:html:response', { 
      success: false, 
      error: error instanceof Error ? error.message : 'Failed to parse HTML' 
    });
  }
});

ipcMain.on('parse:dynamic', async (event, url: string, selector: string) => {
  try {
    const data = await parseDynamicContent(url, selector);
    event.sender.send('parse:dynamic:response', { 
      success: true, 
      data 
    });
  } catch (error) {
    event.sender.send('parse:dynamic:response', { 
      success: false, 
      error: error instanceof Error ? error.message : 'Failed to parse dynamic content' 
    });
  }
});

ipcMain.on('parse:data', async (event, config: ParseConfig) => {
  try {
    // Заглушка - реализуйте вашу логику парсинга
    const result = `Processed ${config.type}: ${config.data}`;
    event.sender.send('parse:data:response', { 
      success: true, 
      data: result 
    });
  } catch (error) {
    event.sender.send('parse:data:response', { 
      success: false, 
      error: error instanceof Error ? error.message : 'Failed to parse data' 
    });
  }
});